\echo 'Session 156 — Matt 26 extras-tier cross-references migration starting...'
BEGIN;

-- Verse-lookup temp view. Mirrors the S146/S154 view; retained for
-- forward compatibility even though Matt 26 surfaces only canon + enoch
-- + apocrypha + pseudepigrapha at S156.
CREATE TEMP VIEW _s156_xref_lookup AS
SELECT
    e.slug AS edition_slug,
    b.slug AS book_slug,
    c.chapter_number,
    v.verse_number,
    v.id AS verse_id
  FROM verses v
  JOIN chapters c ON v.chapter_id = c.id
  JOIN books    b ON c.book_id    = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN (
       'canon',
       'enoch',
       'jubilees',
       'jasher',
       'apocrypha',
       'apocrypha-charles-vol1',
       'pseudepigrapha',
       'adam-eve-conflict',
       'apocalypse-of-abraham',
       'ascension-isaiah',
       'sonnini-acts-29'
   );

-- ---------------------------------------------------------------------
-- Insert 19 extras-tier cross_references rows.
-- ---------------------------------------------------------------------
WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, note) AS (VALUES

  -- Thread 1: the-elect-one-vindicated-on-the-throne-and-the-kings-condemned-in-1-enoch-46-48-62-63
  ('canon', 'matthew', 26, 64, 'enoch', '1-enoch', 46, 2,
   '*And I asked the angel who went with me, who showed me all the hidden things, concerning that Son of Adam, who he was, and whence he was, (and) why he went with the Head of Days?* 1 Enoch 46:2 names the wisdom-stream''s direct articulation of the Son-of-Adam-walking-with-the-Head-of-Days substance — the named-figure standing-beside-the-Father at the heavenly-throne-vision register. The framework reads the verse against Matt 26:64''s *Hereafter shall ye see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* The King-of-Yashar''el (Israel) standing-bound-before-the-Sanhedrin at-the-historical-pivot identifies-himself-as-the-Son-of-Adam-the-1-Enoch-Parables-had-named-the-substance-for centuries before — the substantial-confluence at-the-King''s-own-mouth-substance of the substantial Psalm 110:1 substance (the prophet-David''s Davidic-Lord-at-the-right-hand of Yahuah (the LORD)) + the substantial Daniel 7:13-14 substance the prophet-Daniel walked. Note on the kaph-comparative-narrow-rule per Red Line #12: 1 Enoch 46 reads the substantial-title *the Son of Adam* directly (the named-figure-walking-with-the-Head-of-Days, NOT the kaph-comparative-substance); Daniel 7:13 itself preserves the kaph at the Aramaic-source-register (*kbar enash* = like a son of mortal-man) which is incarnation-honoring; Matt 26:64''s Greek *opsesthe ton huion tou anthrōpou* reads the title-direct (no *hōs* / no *homoion*) — the King at v.64 identifies-himself-as-the-Son-of-Adam Daniel 7''s figure-resembled, the One the kaph at Daniel 7:13 honored. The 1 Enoch named-figure and the King''s-self-identification cohere. FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 26, 64, 'enoch', '1-enoch', 46, 4,
   '*And this Son of Adam whom thou hast seen shall raise up the kings and the mighty from their seats, and the strong from their thrones, and shall loosen the reins of the strong, and break the teeth of the sinners.* 1 Enoch 46:4 names the wisdom-stream''s direct articulation of the Son-of-Adam-vindicated-against-the-kings-and-the-mighty substance. The framework reads the verse against Matt 26:64''s answer-at-the-Sanhedrin — the corrupt-high-priesthood-Sanhedrin-aristocracy condemning-the-King at the historical-pivot will-themselves-be-raised-up-from-their-seats and stand-before-the-Son-of-Adam-on-the-throne-of-his-glory at the eschatological-day-of-vindication. The substantial-irony-substance walks-substantively: the Sanhedrin-substance prices-the-King-as-the-blasphemer-deserving-death at v.66 (*he is guilty of death*) and the same Sanhedrin-substance will-themselves-stand-condemned before the Son-of-Adam-they-condemned at the day 1 Enoch 46:4 names the substance for. The categorical-direct-rule-out of any-reading-that-treats-the-Sanhedrin''s-verdict-as-the-Father''s-verdict — the Father''s-verdict on the Son-at-the-Sanhedrin-trial is the substantial-Davidic-Messianic-Son-at-the-right-hand-of-power-substance the King names at v.64; the Sanhedrin''s-verdict is the corrupt-leadership-substance the Tanakh-prophetic-substance had walked-out-substantively against centuries before.'),

  ('canon', 'matthew', 26, 64, 'enoch', '1-enoch', 48, 3,
   '*Yea, before the sun and the signs were created, before the stars of the heaven were made, His name was named before Yahuah (God) of Spirits.* 1 Enoch 48:3 names the wisdom-stream''s direct articulation of the Son-of-Adam-named-before-the-foundation-of-the-world substance. The framework reads the verse against Matt 26:64''s direct-self-identification — the King-of-Yashar''el (Israel) standing-bound-before-the-Sanhedrin names-himself-as-the-Son-of-Adam-whose-name-was-named-before-Yahuah-of-Spirits before-the-foundation-of-the-world. The substantial-Davidic-Messianic-Son-of-Adam-substance is NOT-the-substantial-substance the Sanhedrin-substance treats-as-blasphemy at-the-historical-pivot; the substantial-substance is the substantial-Father''s-pre-foundational-Naming-of-the-Son-substance the wisdom-stream had named-substantively at-the-heavenly-substance-register. The framework reads this in continuity with the cause-and-effect-of-hearing per Red Line #11 — *if you hear, you are sons of Adam. You did not choose to hear and become these things. You heard because you are these things.* The names-named-before-the-foundation-of-the-world architecture (Revelation 13:8 + 17:8) operates at the substantial-substance-level the wisdom-stream had named-substantively at 1 Enoch 48:3 + 48:6 (*chosen and hidden before Him, before the creation of the world and for evermore*). The Sanhedrin-substance does-NOT-name-the-Son; the Father-substance names-the-Son before-the-creation-of-the-world.'),

  ('canon', 'matthew', 26, 64, 'enoch', '1-enoch', 62, 9,
   '*And this Son of Adam whom thou hast seen shall raise up the kings and the mighty from their seats, and the strong from their thrones, and shall loosen the reins of the strong, and break the teeth of the sinners.* 1 Enoch 62:9 names the wisdom-stream''s articulation of the Son-of-Adam-on-the-throne-of-his-glory vindicated-against-the-kings-and-the-mighty substance — the eschatological-day-of-the-vindication-of-the-Elect-One the Father had-walked-out-substantively at 62:6-7 (*and Yahuah (God) of Spirits seated the Elect One on the throne of His glory* + *this is the Son of Adam who is born unto righteousness*). The framework reads the verse against Matt 26:64''s *coming in the clouds of heaven* — the Daniel 7:13-14 substance the King quotes walks the substantial-everlasting-dominion-substance (*and there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away*); 1 Enoch 62 names the operative-substance the wisdom-stream walks-the-substance-for. The two-substances walk-substantively-at-the-substantial-same-substance the King-of-Yashar''el (Israel) walks-out-substantively at-the-Sanhedrin-trial-substance.'),

  ('canon', 'matthew', 26, 64, 'enoch', '1-enoch', 63, 3,
   '*And all the kings and the mighty and the exalted and those who rule the earth shall fall down on their faces before him and worship and set their hope upon that Son of Adam, and shall petition him and supplicate for mercy at his hands.* 1 Enoch 63:3 names the wisdom-stream''s articulation of the kings-and-the-mighty-falling-down-before-the-Son-of-Adam-on-the-day-of-judgement substance. The framework reads the verse against Matt 26:64-66''s Sanhedrin-condemnation — the corrupt-Sanhedrin-aristocracy condemning-the-King at-the-historical-pivot will-themselves-fall-down-before-the-same-Son-of-Adam-they-condemned at the eschatological-day-of-vindication. The substantial-1-Enoch-63 substance walks-substantively the substantial-direct-articulation of the substantial-Tanakh-substance the prophet-Yeshayahu (Isaiah) walked at Isaiah 45:23 (*unto me every knee shall bow, every tongue shall swear*) and the apostle-Sha''ul (Paul) walks at Philippians 2:10-11 (*at the name of Yahusha (Jesus) every knee should bow* + *every tongue should confess that Yahusha (Jesus) HaMashiach (Christ) is Lord*). The substantial-substance walks the substantial-direct-rule-out of any-Universalist-collapse — the falling-down-on-their-faces of 1 Enoch 63:3 + Isaiah 45:23 + Philippians 2:10-11 is the substantial-acknowledgement-of-the-Son-of-Adam-as-Lord, NOT-substantially-the-categorical-substance-of-the-substantial-universal-saved-substance the modern-Christian-and-Hebrew-Roots-Universalism walks (the acknowledgement-of-Lordship-substance does-not-walk-into-categorical-universal-salvation; the post-acknowledgement-substance walks-substantively-into-the-substantial-day-of-the-vindication-of-the-righteous-and-the-judgement-of-the-wicked-substance per 1 Enoch 63:4-6, 9 + Daniel 7:9-12).'),

  -- Thread 2: the-blood-of-the-new-covenant-and-the-faithful-unto-death-for-the-covenant-in-1-and-2-maccabees
  ('canon', 'matthew', 26, 28, 'apocrypha', '1-maccabees', 1, 63,
   '*Wherefore they chose rather to die, that they might not be defiled with meats, and that they might not profane the holy covenant: so then they died.* 1 Maccabees 1:63 names the wisdom-stream''s direct articulation of the faithful-unto-death-for-the-holy-covenant substance — the Maccabean-faithful-servants the Antiochus-Epiphanes-persecution-substance forced-into-the-substantial-choice between-profaning-the-covenant-and-dying-for-it. The framework reads the verse against Matt 26:28''s *this is my blood of the new testament, which is shed for many for the remission of sins.* The Maccabean-faithful-died-for-the-covenant-of-their-fathers-substance; the King-of-Yashar''el (Israel) dies-as-the-Pesach-lamb-substance to-inaugurate-the-substantial-new-covenant the substantial Jeremiah 31:31-34 substance the prophet-Yirmeyahu (Jeremiah) walked walks-into-substantively (*I will put my law in their inward parts, and write it in their hearts*) — the substantial-new-covenant-substance is-the-Torah-internalized-substance NOT-the-Torah-replaced-substance the inherited-Christian-collapse walks-from. The Maccabean-prefiguring-substance walks the substantial-faithful-unto-death-for-the-Sinai-covenant-substance the Tanakh-Sinai-substance the prophet-Mosheh (Moses) walked at Exodus 24:8 walks (*behold the blood of the covenant, which Yahuah (the LORD) hath made with you concerning all these words*); the King-of-Yashar''el (Israel) walks-substantively the substantial-blood-of-the-new-covenant-substance walked-forward-into the substantial-Torah-internalized-substance-on-the-new-heart Ezekiel 36:26-27 walks-into directly. FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 26, 28, 'apocrypha', '1-maccabees', 2, 50,
   '*Now therefore, my sons, be you zealous for the law, and give your lives for the covenant of your fathers.* 1 Maccabees 2:50 names the wisdom-stream''s direct articulation of the give-your-lives-for-the-covenant-of-your-fathers substance — Mattathias''s deathbed-charge to his sons the Maccabean-revolt-substance walks-out-substantively against Antiochus-Epiphanes. The framework reads the verse against Matt 26:28''s substantial-blood-of-the-new-covenant substance — the King-of-Yashar''el (Israel) walks-substantively-the-substantial-give-the-life-for-the-covenant-substance the Maccabean-substance walks-the-prefiguring-pattern-for; the substantial-substance the King walks-out is the substantial-Pesach-lamb-substance + the substantial-blood-of-the-new-covenant-substance walked-forward-into the substantial-Torah-internalized-substance the prophet-Yechezk''el (Ezekiel) walked at Ezekiel 36:26-27 walks-into directly. The substantial-Mattathias-substance''s *be you zealous for the law* substance walks the substantial-Torah-zeal-substance walks-into the substantial-new-covenant-substance the King-of-Yashar''el (Israel) inaugurates at-the-Last-Supper — the substantial-Torah-internalized-on-the-new-heart-substance the Ruach HaKodesh (Holy Spirit) gives. The framework reads this carefully — the *zealous for the law* substance the Mattathias-substance walks is NOT-substantially-the-flesh-credential-performance-substance the inherited-Pharisaic-and-Galatian-agitator-and-modern-Christian-Judaizer-substance walks; the substantial-substance is the substantial-Torah-substance the substantial-Father-substance walks-out at-Sinai walking-substantively-internalized-on-the-substantial-new-heart-substance the King-of-Yashar''el (Israel) inaugurates at v.28.'),

  ('canon', 'matthew', 26, 28, 'apocrypha', '2-maccabees', 7, 36,
   '*For our brothers, who now have suffered a short pain, are dead under the covenant of Yahuah (God) of everlasting life: but you, through the judgment of Yahuah (God), shall receive just punishment for your pride.* 2 Maccabees 7:36 names the wisdom-stream''s direct articulation of the dead-under-the-covenant-of-Yahuah-of-everlasting-life substance — the Maccabean-seven-sons-and-their-mother''s faithful-unto-death-witness against Antiochus-Epiphanes. The framework reads the verse against Matt 26:28''s substantial-blood-of-the-new-covenant-shed-for-many-for-the-remission-of-sins substance. The Maccabean-seven-sons walk-the-substantial-faithful-unto-death-for-the-covenant-substance + the substantial-resurrection-substance the apostle-Sha''ul (Paul) walks at 1 Corinthians 15:54-55 walks-into (the substantial-everlasting-life-substance the substantial Hosea 13:14 substance the prophet-Hoshea (Hosea) walked walks-into). The King-of-Yashar''el (Israel) walks-substantively-the-substantial-fulfillment-substance the Maccabean-prefiguring-pattern walks-the-substance-for — the substantial-blood-of-the-new-covenant-substance + the substantial-Pesach-lamb-fulfillment-substance + the substantial-resurrection-of-the-third-day-substance the King walks-out at-the-substantial-passion-narrative. The framework reads this in continuity with the cause-and-effect-of-grace per the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md — grace is the door-home, opened by the categorically-blameless-One''s voluntary walking-into-the-shameful-death the substantially-bound owed; the curse-system of Deuteronomy 28 still falls on those who walk contrary to him; Romans 6:15 walks-as-the-immediate-corrective to-Romans-6:14, NOT-substantially-the-categorical-release-from-consequence the inherited-Reformation-eternal-security-collapse walks. The Maccabean-faithful-died-with-the-substantial-everlasting-life-hope-substance; the King walks-substantively-the-substantial-resurrection-fulfillment-substance.'),

  -- Thread 3: the-cup-of-the-faithful-servants-drunk-faithful-unto-death-in-4-maccabees
  ('canon', 'matthew', 26, 39, 'pseudepigrapha', '4-maccabees', 6, 29,
   '*Why dost thou delay, O tyrant? We are ready to die rather than transgress the commandments of our fathers.* 4 Maccabees 6:29 names the wisdom-stream''s direct articulation of the ready-to-die-rather-than-transgress-the-commandments substance — the Maccabean-seven-brothers'' one-voice declaration to Antiochus-Epiphanes. The framework reads the verse against Matt 26:39''s *O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt.* The Maccabean-faithful-servants walk-the-substantial-ready-to-die-rather-than-transgress-the-commandments-substance against the substantial-tyrant-substance; the King-of-Yashar''el (Israel) walks-substantively-the-substantial-cup-of-suffering-substance the substantial Tanakh-cup-of-Yahuah''s-wrath-cluster (Psalm 75:8 + Isaiah 51:17-22 + Jeremiah 25:15-29 + Ezekiel 23:31-34) the King drinks-as-the-substantial-Pesach-lamb-substance for-the-substantial-remission-of-sins-substance. The framework reads this carefully — the Gethsemane-cup-substance is NOT-substantially-the-categorical-physical-suffering-only-substance the modern-Christian-collapse walks-from; the substantial-cup is the substantial-Father''s-cup-of-Yahuah''s-wrath-substance the King-as-the-Suffering-Servant-substance drinks-substantively the substantial Isaiah 53:10 substance the prophet-Yeshayahu (Isaiah) walked walks-into (*yet it pleased Yahuah (the LORD) to bruise him; he hath put him to grief: when thou shalt make his soul an offering for sin*). The Maccabean-prefiguring-substance walks-the-pattern; the King walks-the-substantial-fulfillment-at-the-categorically-greater-substance.'),

  ('canon', 'matthew', 26, 42, 'pseudepigrapha', '4-maccabees', 13, 13,
   '*And righteousness won the victory, and gave the crown to her athletes.* 4 Maccabees 13:13 names the wisdom-stream''s articulation of the righteousness-won-the-victory + the prize-of-victory-in-incorruption-everlasting-life substance the Maccabean-seven-brothers walked-out-substantively faithful-unto-death. The framework reads the verse against Matt 26:42''s second-Gethsemane-prayer (*O my Father, if this cup may not pass away from me, except I drink it, thy will be done*). The Maccabean-faithful-walked-the-endurance-substance-into-the-substantial-prize-of-victory-in-incorruption-everlasting-life; the King-of-Yashar''el (Israel) walks-substantively-the-substantial-drinking-of-the-cup-into-the-substantial-resurrection-of-the-third-day-substance. The substantial *thy will be done* substance walks the substantial-Formless-Source-and-Formed-Expression-substance — the substantial-Father-substance is-the-substantial-Formless-Source-substance, the King-of-Yashar''el (Israel) is-the-substantial-Formed-Expression-substance walking-eternally-submitted-to-the-Formless-Source-substance the apostle-Yochanan (John) walks at John 5:30 and John 8:28-29 walks-substantively. The substantial-substance walks-the-substantial-direct-rule-out of three-inherited-collapses-of-the-substantial-nature-of-Elohim-substance: (a) the Trinitarian-three-co-equal-persons-substance (three-co-equal-persons-substance does-NOT-walk the Gethsemane-substance the Son-submits-to-the-Father); (b) the modalist-collapse-substance (the substantial-distinction-between-the-Father-substance and the King-of-Yashar''el (Israel)-as-the-Son-of-Adam-substance walks-substantively-the-Gethsemane-substance); (c) the Arian-created-being-substance (the substantial-King-of-Yashar''el (Israel)-as-the-Formed-Expression-substance walks-the-substantial-eternal-Word-substance, NOT-a-created-being-substance).'),

  ('canon', 'matthew', 26, 46, 'pseudepigrapha', '4-maccabees', 13, 18,
   '*They having as it were become a ransom for our nation''s sin; and through the blood of these righteous men and the propitiation of their death, the divine Providence delivered Yashar''el (Israel) that before was evil entreated.* 4 Maccabees 13:18 names THE direct wisdom-stream verbal-anchor for the ransom-for-our-nation''s-sin + propitiation-of-their-death-delivered-Yashar''el (Israel) substance — the Maccabean-faithful-servants'' faithful-unto-death-as-the-substantial-prefiguring-substance. The framework reads the verse against Matt 26:46''s *Rise, let us be going: behold, he is at hand that doth betray me* — the King-of-Yashar''el (Israel) walks-substantively into-the-substantial-arrest + the substantial-passion + the substantial-Cross + the substantial-third-day-resurrection. The substantial-Maccabean-prefiguring-substance walks-the-substantial-ransom-and-propitiation-substance at-the-substantial-Maccabean-faithful-servants-substance; the King-of-Yashar''el (Israel)-as-the-Pesach-lamb-substance walks-the-substantial-fulfillment-substance at-the-substantial-categorically-greater-substance the substantial Matthew 20:28 substance the King had-walked walks-into (*the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many*). The framework reads this carefully — the substantial *ransom* (Greek *lytron* + Greek *antallagma*) substance and the substantial *propitiation* (Greek *hilasterion* + Greek *hilasmos*) substance the King walks-out is NOT-substantially-the-forensic-substitutionary-juridical-transaction-substance the inherited-Anselmian-Reformation-Calvinist-collapse walks-from; the substantial-substance is the substantial-Pesach-lamb-fulfillment-substance the Tanakh-Exodus-12-Pesach-substance + the substantial Yom Kippur (Day of Atonement) substance the prophet-Mosheh (Moses) walked at Leviticus 16 walks-into directly + the substantial-Isaiah-53-Suffering-Servant-bearing-the-iniquities-of-the-many-substance walks-into. The Maccabean-prefiguring-substance walks-the-pattern; the King-of-Yashar''el (Israel) walks-the-substantial-fulfillment-at-the-categorically-greater-substance.'),

  -- Thread 4: the-shepherd-smitten-and-the-temple-veil-rent-in-the-testaments-of-the-twelve
  ('canon', 'matthew', 26, 31, 'pseudepigrapha', 'testaments-xii', 17, 2,
   '*Behold, I am clear from your ungodliness and transgression, which ye shall commit in the end of the ages against the Saviour of the world, Messiah (Christ), acting godlessly, deceiving Yashar''el (Israel), and stirring up against it great evils.* Testament of Levi 17:2 names THE direct wisdom-stream verbal-anchor for the corrupt-high-priesthood-at-the-end-of-the-ages-condemning-the-Saviour-of-the-world-Messiah substance. The framework reads the verse against Matt 26:31''s *all ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep of the flock shall be scattered abroad* (the substantial Zechariah 13:7 substance the prophet-Zecharyah (Zechariah) walked at-the-substantial-substance-direct). The substantial-Test.-Levi-substance walks-the-substantial-prefiguring of the corrupt-Sanhedrin-Kaiapha (Caiaphas)-aristocracy-substance the King walks-out-against from-Matthew-21-onward into-the-substantial-Sanhedrin-trial-substance at vv.57-68. The substantial *Saviour of the world, Messiah (Christ)* substance the wisdom-stream had named-substantively at the Test.-Levi-pre-Christian-Tanakh-prefiguring-register (the Charles-Vol2 manuscript-substance may carry-substantial-later-interpolation-substance at-the-substantial-substance, but the substantial-architecture-of-the-corrupt-high-priesthood-condemning-the-faithful-Saviour-of-the-world-Messiah-substance walks the substantial-pre-Christian-Tanakh-substance the substantial-Maccabean-period-substance walked-out-substantively). The framework reads this in continuity with the framework-deep''s *Judaizer Error* section — the corrupt-leadership-substance the King walks-out-against is the corrupt-second-Temple-priestly-aristocracy-substance the wisdom-stream had named-the-substance-for at-the-substantial-Test.-Levi-substance, NEVER-against-the-Yahudi (Jewish)-people-substance the King walks-himself-as-a-Yahudi (Jew)-substance-of-the-tribe-of-Yahudah (Judah)-substance. System-not-people posture holds non-negotiable.'),

  ('canon', 'matthew', 26, 65, 'pseudepigrapha', 'testaments-xii', 17, 3,
   '*And ye shall deal lawlessly together with Yashar''el (Israel), so He shall not bear with Jerusalem because of your wickedness; but the veil of the temple shall be rent, so as not to cover your shame. And ye shall be scattered as captives among the Gentiles, and shall be for a reproach.* Testament of Levi 17:3 names THE direct wisdom-stream verbal-anchor for the veil-of-the-temple-shall-be-rent + the corrupt-priesthood-scattered-as-captives substance. The framework reads the verse against Matt 26:65''s *Then the high priest rent his clothes, saying, He hath spoken blasphemy.* The high-priest-Kaiapha (Caiaphas)-substance violates the substantial Leviticus 10:6 + 21:10 substance the prophet-Mosheh (Moses) walked at-the-substantial-substance-direct (*let not the hair of your heads, neither rend your clothes* + *the high priest among his brethren, upon whose head the anointing oil was poured, and that is consecrated to put on the garments, shall not uncover his head, nor rend his clothes*) — the substantial-high-priestly-rending-of-the-clothes is-substantially-the-Tanakh-prohibition the substantial-Sanhedrin-Kaiapha (Caiaphas)-substance violates-substantively at-the-substantial-substance-of-the-corrupt-high-priesthood-at-the-end-of-the-ages-substance. The substantial-Test.-Levi-17:3 substance walks-the-substantial-prefiguring-substance — the substantial-veil-of-the-temple-shall-be-rent-substance walks-into-substantively-the substantial Matthew 27:51 substance (*and, behold, the veil of the temple was rent in twain from the top to the bottom*) at-the-Cross-substance the substantial-Father-substance walks-out-substantively the substantial-end-of-the-substantial-Second-Temple-corrupt-priestly-aristocracy-substance + the substantial-direct-access-of-the-substantial-citizens-of-the-substantial-kingdom-to-the-substantial-Father-through-the-substantial-King-of-Yashar''el (Israel)-as-the-substantial-High-Priest-substance the apostle-Sha''ul (Paul) walks at Hebrews 4:14-16 and Hebrews 10:19-22 walks-into directly.'),

  ('canon', 'matthew', 26, 28, 'pseudepigrapha', 'testaments-xii', 88, 31,
   '*The blameless one shall be defiled for lawless men, the sinless one shall die for ungodly men, in the blood of the covenant, for the salvation of the Gentiles and of Yashar''el (Israel).* Testament of Benjamin 88:31 names THE direct wisdom-stream verbal-anchor for the blameless-one-defiled-for-lawless-men + the sinless-one-die-for-ungodly-men + the blood-of-the-covenant-for-the-salvation-of-Yashar''el (Israel) substance. The framework reads the verse against Matt 26:28''s *this is my blood of the new testament, which is shed for many for the remission of sins.* The substantial-Test.-Benjamin-substance walks-the-direct-prefiguring-substance — the substantial-blood-of-the-covenant-substance + the substantial-shed-for-many-substance + the substantial-remission-of-sins-substance the wisdom-stream had named-substantively at-the-Test.-Benjamin-register-the-substantial-pre-Christian-Maccabean-period-substance walked-out-substantively. The framework reads this carefully — the substantial *salvation of the Gentiles* substance the Test.-Benjamin-substance walks is the substantial-Tanakh-prophetic-substance the prophet-Yeshayahu (Isaiah) walked at Isaiah 49:6 (*it is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Yashar''el (Israel): I will also give thee for a light to the Gentiles, that thou mayest be my salvation unto the end of the earth*) walks-into directly. The substantial *gathering of the twelve tribes from the scattering-substance* + the substantial *light to the Gentiles* substance walk-substantively-at-the-substantial-same-substance per Red Line #7 + Red Line #11 — the wild-olive-branches-the-living-descendants-of-the-broken-off are-the-substantial-scattered-seed-of-the-house-of-Yashar''el (Israel)-substance the substantial-King-of-Yashar''el (Israel)-as-the-Pesach-lamb-substance walks-substantively the substantial-gathering-of-the-substantial-twelve-tribes-substance through-the-substantial-new-covenant-substance the substantial-blood-of-the-covenant-substance inaugurates. NOT-the-categorical-Gentile-grafting-by-faith-confession-substance the inherited-Christian-collapse walks; the substantial-Gentiles-substance the Test.-Benjamin-substance walks is the substantial-nations-among-whom-the-scattered-seed-have-been-scattered-substance, walked-substantively the substantial-citizens-of-the-substantial-kingdom-substance the substantial-Father-substance walks-out-substantively the substantial-broadcast-of-the-gospel-substance the King-of-Yashar''el (Israel) walks-out at Matthew 24:14 + Matthew 28:19 walks-into substantively.'),

  -- Thread 5: the-betrayer-the-double-tongue-and-the-watch-against-temptation-in-sirach
  ('canon', 'matthew', 26, 25, 'apocrypha', 'ecclesiasticus', 6, 1,
   '*Instead of a friend become not an enemy; for thereby you shall inherit an ill name, shame, and reproach: even so shall a sinner that has a double tongue.* Sirach (Ecclesiasticus) 6:1 names the wisdom-stream''s direct articulation of the friend-become-enemy + the sinner-that-has-a-double-tongue substance. The framework reads the verse against Matt 26:25''s *Then Yahudah (Judas), which betrayed him, answered and said, Master, is it I? He said unto him, Thou hast said.* The substantial-Yahudah-Iscariot (Judas Iscariot)-substance walks-substantively the substantial-friend-become-enemy + the substantial-double-tongue-substance the wisdom-stream had named-substantively the substance-for. The substantial-Yahudah-Iscariot (Judas Iscariot)-substance asks the substantial-question *Master, is it I?* at-the-substantial-Last-Supper after-having-already-walked-out-the-betrayal-bargain at vv.14-16 (the substantial *thirty pieces of silver* substance the substantial Zechariah 11:12-13 substance the prophet-Zecharyah (Zechariah) walked walks-into) — the substantial-double-tongue-substance the wisdom-stream had named-substantively, the substantial *Master, is it I?* substance is the substantial-question-of-the-double-tongue-substance the Yahudah-Iscariot-substance walks at-the-substantial-substance-of-the-substantial-betrayal-already-walked-out-substantively-secretly. The framework reads this carefully — the substantial-Yahudah-Iscariot (Judas Iscariot)-substance is NOT-substantially-the-categorical-determinism-substance the inherited-Reformation-collapse walks; the substantial-Father''s-prophetic-purpose-substance walks-substantively AND the substantial-Yahudah-Iscariot (Judas Iscariot)-substance''s individual-choice-substance walks-substantively both-substances-at-the-same-substance per the framework''s reading of the apostle-Yochanan (John) at John 13:2 (*the devil having now put into the heart of Yahudah (Judas) Iscariot ... to betray him*) and John 13:27 (*after the sop Satan entered into him*).'),

  ('canon', 'matthew', 26, 49, 'apocrypha', 'ecclesiasticus', 12, 16,
   '*An enemy speaks sweetly with his lips, but in his heart he imagineth how to throw you into a pit: he will weep with his eyes, but if he find opportunity, he will not be satisfied with blood.* Sirach (Ecclesiasticus) 12:16 names the wisdom-stream''s direct articulation of the enemy-who-speaks-sweetly-with-his-lips-while-imagining-the-pit substance. The framework reads the verse against Matt 26:49''s *And forthwith he came to Yahusha (Jesus), and said, Hail, master; and kissed him.* The substantial-Yahudah-Iscariot (Judas Iscariot)-substance walks-substantively the substantial-enemy-who-speaks-sweetly-with-his-lips-substance the wisdom-stream had named-substantively the substance-for. The substantial-kiss-of-the-enemy-substance walks the substantial Proverbs 27:6 substance the prophet-Shlomo (Solomon) walked (*the kisses of an enemy are deceitful*) + the substantial Psalm 55:12-14 substance the prophet-David walked (*for it was not an enemy that reproached me; then I could have borne it ... but it was thou, a man mine equal, my guide, and mine acquaintance*). The substantial-Sirach 12:16-substance + the substantial Proverbs 27:6-substance + the substantial Psalm 55:12-14-substance all-three-substances walk-substantively-at-the-substantial-same-substance the substantial-Yahudah-Iscariot (Judas Iscariot)-substance walks-out at-the-substantial-arrest-substance. The substantial-Tanakh-wisdom-stream-substance and the substantial-Tanakh-Psalter-substance and the substantial-Tanakh-Proverbs-substance all-three-substances walk-substantively-the-substantial-prefiguring of the substantial-Yahudah-Iscariot (Judas Iscariot)-betrayer-substance.'),

  ('canon', 'matthew', 26, 50, 'apocrypha', 'ecclesiasticus', 37, 2,
   '*Is it not a grief to death, when a companion and friend is turned to an enemy?* Sirach (Ecclesiasticus) 37:2 names the wisdom-stream''s direct articulation of the grief-to-death-when-a-companion-and-friend-is-turned-to-an-enemy substance. The framework reads the verse against Matt 26:50''s *And Yahusha (Jesus) said unto him, Friend, wherefore art thou come?* The substantial-King-of-Yashar''el (Israel)''s *Friend* (Greek *hetaire*) address to the substantial-Yahudah-Iscariot (Judas Iscariot)-substance at-the-substantial-arrest is the substantial-grief-of-the-King-at-the-substantial-companion-and-friend-turned-to-an-enemy-substance the wisdom-stream had named-substantively the substance-for. The substantial-grief-substance walks the substantial Psalm 41:9 substance the prophet-David walked (*yea, mine own familiar friend, in whom I trusted, which did eat of my bread, hath lifted up his heel against me*) the King-of-Yashar''el (Israel) cites at John 13:18 walks-into-substantively. The substantial-King-of-Yashar''el (Israel)-substance walks-substantively-the-substantial-grief-to-death-substance the substantial Matthew 26:38 substance (*my soul is exceeding sorrowful, even unto death*) walks-substantively-the-substantial-substance-of-the-substantial-grief-to-death-the-companion-and-friend-turned-to-an-enemy-substance the wisdom-stream had named-substantively. The framework reads this in continuity with the substantial-Suffering-Servant-substance the prophet-Yeshayahu (Isaiah) walked at Isaiah 53:3 (*he is despised and rejected of men; a man of sorrows, and acquainted with grief*) walks-into directly.'),

  ('canon', 'matthew', 26, 41, 'apocrypha', 'ecclesiasticus', 2, 1,
   '*My son, if you come to serve Yahuah (God), prepare your soul for temptation.* Sirach (Ecclesiasticus) 2:1 names THE direct wisdom-stream verbal-anchor for the prepare-your-soul-for-temptation substance — the wisdom-stream''s opening of the come-to-serve-Yahuah-prepare-for-temptation diagnostic. The framework reads the verse against Matt 26:41''s *Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak.* The substantial-King-of-Yashar''el (Israel)-substance''s teaching to the disciples at-the-Gethsemane-substance walks-substantively-the-substantial-prepare-the-soul-for-temptation-substance the wisdom-stream had named-substantively. The substantial-disciples-falling-asleep-substance walks the substantial-flesh-weakness-substance the prophet-David walked at Psalm 51:5 + Psalm 103:14 (*for he knoweth our frame; he remembereth that we are dust*) walks-into directly. The framework reads this in continuity with the cause-and-effect-of-the-new-heart per the framework-deep''s *Grace, the Way, the New Heart, and the Mercy of Depart* section — the substantial-flesh-weakness-substance is the substantial-substance-of-the-substantial-Adamic-fall-substance the substantial-citizens-of-the-substantial-kingdom-substance walk-substantively against-the-substantial-flesh-weakness-substance through-the-substantial-Ruach HaKodesh (Holy Spirit)-internalizing-the-Torah-on-the-substantial-new-heart-substance the prophet-Yechezk''el (Ezekiel) walked at Ezekiel 36:26-27 walks-into directly (*and I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them*). The substantial-Sirach 2:1 substance walks-substantively the substantial-pre-Christian-Tanakh-Maccabean-period-wisdom-stream-substance walked-out-substantively the substantial-substance-of-the-substantial-preparation-substance.'),

  ('canon', 'matthew', 26, 75, 'apocrypha', 'ecclesiasticus', 2, 5,
   '*For gold is tried in the fire, and acceptable men in the furnace of adversity.* Sirach (Ecclesiasticus) 2:5 names the wisdom-stream''s direct articulation of the gold-tried-in-the-fire + the acceptable-men-in-the-furnace-of-adversity substance — the wisdom-stream''s articulation of the substantial-refining-of-the-substantial-faithful-substance through-the-substantial-trial-and-suffering-substance. The framework reads the verse against Matt 26:75''s *And Kefa (Peter) remembered the word of Yahusha (Jesus), which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly.* The substantial-Kefa (Peter)-substance walks-substantively-the-substantial-furnace-of-adversity-substance — the substantial-three-fold-denial-substance + the substantial-cock-crowing-substance + the substantial-bitter-weeping-substance walk-substantively-the-substantial-refining-substance the substantial-Kefa (Peter)-substance walks-into-substantively. The substantial-bitter-weeping-substance walks the substantial Psalm 51:17 substance the prophet-David walked at-the-substantial-substance-direct (*the sacrifices of Elohim (God) are a broken spirit: a broken and a contrite heart, O Elohim (God), thou wilt not despise*) + the substantial Joel 2:12-13 substance the prophet-Yo''el (Joel) walked (*rend your heart, and not your garments*) walks-into-substantively. The substantial-Kefa (Peter)-substance walks-the-rend-his-heart-substance, NOT-substantially-the-Sanhedrin-Kaiapha (Caiaphas)-rending-the-garments-superficial-substance at v.65 — the substantial-rending-of-the-heart-substance walks-substantively-the-substantial-repentance-into-the-substantial-restoration-substance the King walks-out at John 21:15-19. The framework reads this carefully — the substantial-Kefa (Peter)-substance walks-the-disciple-falling-into-the-pattern-of-the-faithless-generation-substance per the substantial 2 Esdras (4 Ezra) 7:48 substance the S154 thread 4 anchor-substance walked (*O thou Adam, what hast thou done? for though it was thou that sinned, the fall was not thine alone, but ours also that come of thee*); the substantial *and he went out, and wept bitterly* substance walks the substantial-disciple''s-repentance-tear-substance that breaks-the-generational-pattern by the substantial-kingdom-grace-substance the substantial-Ruach HaKodesh (Holy Spirit)-internalized-Torah-and-the-new-heart-substance the prophet-Yechezk''el (Ezekiel) walked at Ezekiel 36:26-27 walks-into directly. The substantial-direct-rule-out of the categorical-Reformation-eternal-security-substance — the substantial-Kefa (Peter)-substance has-substantively-failed + walks-the-bitter-weeping + walks-the-restoration through-the-substantial-walking-the-repentance-substance, NOT-categorically-once-saved-always-saved.')

)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, 'extras'::content_tier
  FROM input i
  JOIN _s156_xref_lookup sv ON sv.edition_slug   = i.src_edition
                           AND sv.book_slug      = i.src_slug
                           AND sv.chapter_number = i.src_ch
                           AND sv.verse_number   = i.src_v
  JOIN _s156_xref_lookup tv ON tv.edition_slug   = i.tgt_edition
                           AND tv.book_slug      = i.tgt_slug
                           AND tv.chapter_number = i.tgt_ch
                           AND tv.verse_number   = i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

