-- Thread 1 (sort 352): the-elect-one-vindicated-on-the-throne-and-the-kings-condemned-in-1-enoch-46-48-62-63
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-elect-one-vindicated-on-the-throne-and-the-kings-condemned-in-1-enoch-46-48-62-63',
       'The Elect-One vindicated on the throne and the kings-and-the-mighty condemned — 1 Enoch 46 + 48 + 62 + 63''s Son-of-Adam-Parables witness to Matt 26:64''s Sanhedrin-trial answer (FRAMEWORK-MAJOR)',
       'Matt 26:64''s substantial-confluence at-the-King-of-Yashar''el (Israel)''s-own-mouth — *Hereafter shall ye see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven* — the substantial-direct-self-identification of the King-of-Yashar''el (Israel) standing-bound-before-the-Sanhedrin-Kaiapha (Caiaphas) on-oath at-the-historical-pivot, combining the substantial Psalm 110:1 substance the prophet-David walked (*Yahuah (the LORD) said unto my Lord, Sit thou on my right hand, until I make thine enemies thy footstool*) and the substantial Daniel 7:13-14 substance the prophet-Daniel walked (*one like the Son of Adam came with the clouds of heaven ... his dominion is an everlasting dominion*) — read against the wisdom-stream''s direct articulation of the substantial-Son-of-Adam-Elect-One-named-before-the-foundation-of-the-world-and-vindicated-on-the-throne-of-his-glory-against-the-kings-and-the-mighty substance the substantial 1 Enoch Parables (chs 37-71) carries-substantively. Five moves: 1 Enoch 46:2 names the wisdom-stream''s direct articulation of the Son-of-Adam-walking-with-the-Head-of-Days substance (the named-figure standing-beside-the-Father at the heavenly-throne-vision register); 1 Enoch 46:4 names the Son-of-Adam-vindicated-against-the-kings-and-the-mighty-from-their-seats substance (the substantial-irony the Sanhedrin-condemning-the-King-at-the-historical-pivot will-themselves-stand-condemned at the eschatological-day); 1 Enoch 48:3 names the Son-of-Adam-named-before-the-foundation-of-the-world substance (in continuity with the names-named-before-the-foundation-of-the-world architecture of Revelation 13:8 + 17:8 per Red Line #11); 1 Enoch 62:9 names the Son-of-Adam-on-the-throne-of-his-glory-vindicated substance (the operative-substance the Daniel 7:13-14 everlasting-dominion-substance walks-into); 1 Enoch 63:3 names the kings-and-the-mighty-falling-down-on-their-faces-before-the-Son-of-Adam substance (the substantial-acknowledgement-of-Lordship-at-the-day-of-judgement the Tanakh-Isaiah-45:23 and apostolic-Philippians-2:10-11 walks-substantively-at-the-substantial-same-substance). The framework reads the cluster as FRAMEWORK-MAJOR for the Son-of-Adam-architecture per Red Line #12. Note on the kaph-comparative-narrow-rule: Matt 26:64''s Greek *opsesthe ton huion tou anthrōpou* reads the title-direct (no *hōs* / no *homoion*); the Daniel 7:13 verse-the-King-quotes preserves the kaph at the Aramaic-source-register (*kbar enash* = like a son of mortal-man) which is incarnation-honoring; 1 Enoch 46:2 / 46:4 / 48:3 / 62:9 / 63:3 read the named-figure substance directly (NOT the kaph-comparative-substance the Daniel 7:13 text-itself preserves). At Matt 26:64 the King identifies-himself-as-the-Son-of-Adam Daniel 7''s figure-resembled — the One the kaph at Daniel 7:13 honored, the One 1 Enoch named-substantively-the-substance-for at the named-figure register. The wisdom-stream-Parables and the King''s-self-identification cohere. System-not-people posture holds non-negotiable — the substantial-substance walks against the corrupt-Sanhedrin-aristocracy-substance the King walks-out-against from-Matthew-21-onward, NEVER-against-the-Yahudi (Jewish)-people-substance the King walks-himself-as-a-Yahudi (Jew)-substance-of-the-tribe-of-Yahudah (Judah).',
       sv.verse_id, ev.verse_id, 'complete_study', 352
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 57
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 26 AND ev.verse_number = 68
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 353): the-blood-of-the-new-covenant-and-the-faithful-unto-death-for-the-covenant-in-1-and-2-maccabees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-blood-of-the-new-covenant-and-the-faithful-unto-death-for-the-covenant-in-1-and-2-maccabees',
       'The blood of the new covenant and the faithful-unto-death for the covenant — 1 Maccabees + 2 Maccabees'' Maccabean-faithful-servants prefiguring of the Last-Supper''s new-covenant-substance (FRAMEWORK-MAJOR)',
       'Matt 26:17-30''s Last-Supper / Pesach (Passover) — the King-of-Yashar''el (Israel) walks-out the substantial-Pesach-meal-substance the substantial-Torah-substance walks at Exodus 12:1-14 + Deuteronomy 16:1-8 AND invests-with-the-substantial-Pesach-lamb-fulfillment-substance the apostle-Sha''ul (Paul) walks at 1 Corinthians 5:7 (*Messiah (Christ) our passover is sacrificed for us*) — read against the wisdom-stream''s direct articulation of the substantial-faithful-unto-death-for-the-holy-covenant + the substantial-dead-under-the-covenant-of-Yahuah-of-everlasting-life substance the substantial 1 and 2 Maccabees carry. Three moves: 1 Maccabees 1:63 names the substantial-faithful-unto-death-for-the-holy-covenant substance (the Maccabean-faithful-chose-rather-to-die-than-profane-the-holy-covenant against Antiochus-Epiphanes); 1 Maccabees 2:50 names Mattathias''s substantial-give-your-lives-for-the-covenant-of-your-fathers deathbed-charge to his sons (the substantial-Torah-zeal-substance walks-into-substantively); 2 Maccabees 7:36 names the substantial-dead-under-the-covenant-of-Yahuah-of-everlasting-life substance (the Maccabean-seven-sons-and-their-mother''s faithful-unto-death-witness + the substantial-resurrection-substance the King walks-the-substantial-fulfillment-substance at-the-third-day). The framework reads the cluster as FRAMEWORK-MAJOR. The substantial-new-covenant-substance the King-of-Yashar''el (Israel) inaugurates at v.28 (*this is my blood of the new testament, which is shed for many for the remission of sins*) walks the substantial Jeremiah 31:31-34 substance the prophet-Yirmeyahu (Jeremiah) walked at-the-substantial-substance-direct (*I will put my law in their inward parts, and write it in their hearts*) + the substantial Ezekiel 36:26-27 substance the prophet-Yechezk''el (Ezekiel) walked at-the-substantial-substance-direct (*a new heart also will I give you, and a new spirit will I put within you ... and cause you to walk in my statutes*) — the substantial-new-covenant-substance is-the-Torah-internalized-on-the-substantial-new-heart-substance NOT-the-Torah-replaced-substance the inherited-Christian-collapse walks-from per Red Line #4 + #5 + #6. The substantial-blood-of-the-new-covenant-substance walks the substantial Exodus 24:8 substance (*behold the blood of the covenant*) walked-substantively-forward into-the-substantial-blood-of-the-King-of-Yashar''el (Israel)-as-the-Pesach-lamb-substance; the Maccabean-faithful-died-with-the-substantial-everlasting-life-hope-substance, prefiguring-the-substantial-fulfillment the King walks-out-substantively. The substantial *shed for many* (Greek *peri pollōn*) substance walks the substantial Isaiah 53:10-12 substance + Matthew 20:28 substance the King had-walked walks-into-substantively — the substantial *many* substance is the substantial-twelve-tribes-of-Yashar''el (Israel)-gathered-from-the-substantial-scattering-substance, NOT-substantially-the-Calvinist-limited-atonement-pre-determined-elect-substance NOR-substantially-the-Universalist-categorical-all-humans-substance.',
       sv.verse_id, ev.verse_id, 'complete_study', 353
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 17
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 26 AND ev.verse_number = 30
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 354): the-cup-of-the-faithful-servants-drunk-faithful-unto-death-in-4-maccabees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-cup-of-the-faithful-servants-drunk-faithful-unto-death-in-4-maccabees',
       'The cup of the faithful servants drunk faithful-unto-death — 4 Maccabees 6 + 13''s Maccabean-faithful prefiguring of Gethsemane''s cup-of-suffering substance',
       'Matt 26:36-46''s Gethsemane — the King-of-Yashar''el (Israel)''s substantial-cup-of-suffering-prayer (*O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt* + *O my Father, if this cup may not pass away from me, except I drink it, thy will be done*), the watching-disciples-falling-asleep, *the spirit indeed is willing, but the flesh is weak*, and the three-fold-prayer-substance — read against the wisdom-stream''s direct articulation of the Maccabean-faithful-servants-drinking-the-cup-faithful-unto-death-as-ransom-and-propitiation-for-the-nation substance the substantial 4 Maccabees carries-substantively. Three moves: 4 Maccabees 6:29 names the substantial-Maccabean-seven-brothers'' one-voice declaration to Antiochus-Epiphanes (*we are ready to die rather than transgress the commandments of our fathers* — the substantial-ready-to-die-for-the-covenant-substance the wisdom-stream walks-substantively-the-prefiguring-substance-for); 4 Maccabees 13:13 names the substantial-righteousness-won-the-victory + the prize-of-victory-in-incorruption-everlasting-life substance the Maccabean-faithful-walked-substantively the substantial-endurance-substance into-the-substantial-resurrection; 4 Maccabees 13:18 names THE direct verbal-anchor for the ransom-for-our-nation''s-sin + the propitiation-of-their-death-delivered-Yashar''el (Israel) substance — the Maccabean-faithful-servants'' faithful-unto-death-walked-substantively-the-substantial-prefiguring-substance the King walks-substantively-the-substantial-fulfillment-substance at-the-substantial-categorically-greater-substance. The framework reads the cluster carefully — the substantial-Gethsemane-cup-substance is the substantial-Father''s-cup-of-Yahuah (the LORD)''s-wrath-substance the substantial Tanakh-cup-of-wrath-cluster the prophets walked (Psalm 75:8 + Isaiah 51:17-22 + Jeremiah 25:15-29 + Ezekiel 23:31-34) the King-as-the-Suffering-Servant-substance drinks-substantively for-the-substantial-remission-of-sins-substance, NOT-substantially-the-categorical-physical-suffering-only-substance the modern-Christian-collapse walks-from. The substantial *ransom* and *propitiation* substance the 4 Maccabees walks is NOT-substantially-the-forensic-substitutionary-juridical-transaction-substance the inherited-Anselmian-Reformation-Calvinist-collapse walks-from; the substantial-substance is the substantial-Pesach-lamb-fulfillment-substance the Tanakh-Exodus-12-Pesach-substance + the substantial Yom Kippur (Day of Atonement) substance Leviticus 16 + Isaiah-53-Suffering-Servant-bearing-the-iniquities-of-the-many-substance walks-into directly. The substantial *not as I will, but as thou wilt* substance walks the substantial-Formless-Source-and-Formed-Expression-substance — the substantial-direct-rule-out of three-inherited-collapses (Trinitarian-three-co-equal-persons, modalist-collapse, Arian-created-being) per the framework''s nature-of-God reading.',
       sv.verse_id, ev.verse_id, 'complete_study', 354
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 36
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 26 AND ev.verse_number = 46
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 355): the-shepherd-smitten-and-the-temple-veil-rent-in-the-testaments-of-the-twelve
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-shepherd-smitten-and-the-temple-veil-rent-in-the-testaments-of-the-twelve',
       'The shepherd-smitten + the temple-veil-rent + the blameless-one-defiled-for-lawless-men-in-the-blood-of-the-covenant — Testaments of the Twelve Patriarchs (Test. Levi 17 + Test. Benjamin) prefiguring of Matt 26''s Sanhedrin-trial, the new-covenant-blood, and the scattering-of-the-disciples',
       'Matt 26''s substantial-three-fold-architecture — (1) the substantial-blood-of-the-new-covenant at v.28 (*this is my blood of the new testament, which is shed for many for the remission of sins*); (2) the substantial-Olivet-prediction-of-the-scattering at v.31 (*all ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep of the flock shall be scattered abroad* — the substantial Zechariah 13:7 substance the prophet-Zecharyah (Zechariah) walked walks-into-substantively); (3) the substantial-Sanhedrin-trial-Kaiapha (Caiaphas)-tearing-of-garments at v.65 — the substantial-corrupt-high-priesthood-at-the-end-of-the-ages-condemning-the-Saviour-of-the-world-Messiah architecture — read against the wisdom-stream''s direct articulation of (a) the corrupt-high-priesthood-at-the-end-of-the-ages-substance Test. Levi 17 names, (b) the veil-of-the-temple-shall-be-rent-substance Test. Levi 17:3 names directly, and (c) the blameless-one-defiled-for-lawless-men + the blood-of-the-covenant-for-the-salvation-of-Yashar''el (Israel) substance Test. Benjamin 88:31 names directly. Three moves: Test. Levi 17:2 names THE direct verbal-anchor for the corrupt-high-priesthood-at-the-end-of-the-ages-condemning-the-Saviour-of-the-world-Messiah substance (the framework reads the substance in continuity with the framework-deep''s *Judaizer Error* section — the corrupt-leadership-substance the King walks-out-against is the corrupt-second-Temple-priestly-aristocracy-substance, NEVER-against-the-Yahudi (Jewish)-people; system-not-people posture holds non-negotiable); Test. Levi 17:3 names THE direct verbal-anchor for the veil-of-the-temple-shall-be-rent-substance (the substantial-Matthew-27:51 substance walks-into-substantively at-the-Cross — the substantial-end-of-the-Second-Temple-corrupt-priestly-aristocracy-substance + the substantial-direct-access-of-the-citizens-of-the-kingdom-to-the-Father-through-the-King-of-Yashar''el (Israel)-as-the-High-Priest-substance Hebrews 4:14-16 + 10:19-22 walks-into); Test. Benjamin 88:31 names THE direct verbal-anchor for the blameless-one-defiled-for-lawless-men + the sinless-one-die-for-ungodly-men + the blood-of-the-covenant-for-the-salvation-of-Yashar''el (Israel) substance (the substantial-prefiguring of v.28''s substantial-blood-of-the-new-covenant-shed-for-many-for-the-remission-of-sins-substance). The framework reads the cluster carefully — the substantial *salvation of the Gentiles* substance at Test. Benjamin 88:31 walks the substantial Tanakh-prophetic-substance the prophet-Yeshayahu (Isaiah) walked at Isaiah 49:6 (*it is a light thing that thou shouldest be my servant to raise up the tribes of Jacob, and to restore the preserved of Yashar''el (Israel): I will also give thee for a light to the Gentiles*) walks-into directly; the substantial-Gentiles-substance the Test. Benjamin walks is the substantial-nations-among-whom-the-scattered-seed-have-been-scattered-substance, NOT-the-categorical-Gentile-grafting-by-faith-confession-substance the inherited-Christian-false-inclusion-collapse walks per Red Line #7 + #11. The substantial-gathering-of-the-substantial-twelve-tribes-of-Yashar''el (Israel)-from-the-scattering-substance walks-substantively-through-the-substantial-new-covenant-substance the substantial-blood-of-the-covenant-substance inaugurates.',
       sv.verse_id, ev.verse_id, 'complete_study', 355
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 28
