-- Thread 5 (sort 356): the-betrayer-the-double-tongue-and-the-watch-against-temptation-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-betrayer-the-double-tongue-and-the-watch-against-temptation-in-sirach',
       'The betrayer + the double-tongue + the watch-against-temptation + the bitter-weeping-into-restoration — Sirach (Ecclesiasticus) on the Yahudah-Iscariot (Judas Iscariot)-betrayer-architecture, the Gethsemane-watching-substance, and the Kefa (Peter)-denial-into-repentance substance',
       'Matt 26''s substantial-three-fold-disciple-architecture — (1) the substantial-Yahudah-Iscariot (Judas Iscariot)-betrayer-substance at vv.14-16, vv.20-25, and the kiss at v.49; (2) the substantial-Gethsemane-watching-substance at vv.36-46 (the disciples falling asleep + the King''s *watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak*); (3) the substantial-Kefa (Peter)-three-fold-denial-substance at vv.69-75 + the substantial-bitter-weeping at v.75 — read against the wisdom-stream''s direct articulation of (a) the friend-become-enemy + the sinner-with-the-double-tongue substance, (b) the prepare-the-soul-for-temptation + the gold-tried-in-the-fire substance, and (c) the enemy-speaking-sweetly-with-the-lips-while-imagining-the-pit substance the substantial Sirach (Ecclesiasticus) carries-substantively. Five moves: Sirach 6:1 names the substantial-friend-become-enemy + sinner-with-the-double-tongue substance (the substantial-Yahudah-Iscariot (Judas Iscariot)''s *Master, is it I?* at v.25 walks-substantively-the-double-tongue-substance the wisdom-stream had named-the-substance-for); Sirach 12:16 names the substantial-enemy-who-speaks-sweetly-with-the-lips-while-imagining-the-pit substance (the substantial-Yahudah-Iscariot (Judas Iscariot)''s kiss at v.49 walks-substantively in continuity with Proverbs 27:6''s *the kisses of an enemy are deceitful* + Psalm 55:12-14''s *for it was not an enemy that reproached me ... but it was thou, a man mine equal, my guide, and mine acquaintance*); Sirach 37:2 names the substantial-grief-to-death-when-a-companion-and-friend-is-turned-to-an-enemy substance (the King''s *Friend, wherefore art thou come?* at v.50 + the King''s *my soul is exceeding sorrowful, even unto death* at v.38 — the substantial-Suffering-Servant-grief-substance Isaiah 53:3 walks-into); Sirach 2:1 names THE direct verbal-anchor for the prepare-your-soul-for-temptation substance (the King''s *watch and pray, that ye enter not into temptation* at v.41 walks-substantively the substantial-pre-Christian-Tanakh-wisdom-stream-substance the prophet-David walked at Psalm 51:5 + 103:14 walks-into); Sirach 2:5 names the substantial-gold-tried-in-the-fire + the acceptable-men-in-the-furnace-of-adversity substance (the substantial-Kefa (Peter)-three-fold-denial-substance + the bitter-weeping at v.75 walks-substantively-the-substantial-furnace-of-adversity-substance + the substantial-rending-of-the-heart-into-restoration-substance the substantial Psalm 51:17 + Joel 2:12-13 + John 21:15-19 walks-into). The framework reads the cluster carefully — the substantial-Kefa (Peter)-substance walks-the-disciple-falling-into-the-pattern-of-the-faithless-generation-substance per the substantial 2 Esdras (4 Ezra) 7:48 substance the S154 thread 4 anchor walked (*O thou Adam, what hast thou done? ... the fall was not thine alone, but ours also that come of thee*); the substantial *and he went out, and wept bitterly* substance walks the substantial-disciple''s-repentance-tear-substance that breaks-the-generational-pattern by the substantial-kingdom-grace through-the-substantial-Ruach HaKodesh (Holy Spirit)-internalized-Torah-on-the-new-heart substance Ezekiel 36:26-27 walks-into directly. The substantial-direct-rule-out of the categorical-Reformation-eternal-security-substance — Kefa (Peter) has-failed + walks-the-bitter-weeping + walks-the-restoration through-the-walking-the-repentance-substance, NOT-categorically-once-saved-always-saved (Red Line #2 + the framework-deep''s *Grace, the Way, the New Heart, and the Mercy of Depart* section). System-not-people posture holds non-negotiable — the substance walks-against the substantial-betrayer-architecture and the substantial-faithless-flesh-weakness-substance, NEVER against the substantial-disciples-as-people; the substantial-disciples-substance are the substantial-citizens-of-the-substantial-kingdom-substance walking-substantively-into-the-substantial-restoration-substance through-the-substantial-bitter-weeping-substance the King walks-out at-the-substantial-substance.',
       sv.verse_id, ev.verse_id, 'complete_study', 356
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26 AND sv.verse_number = 14
