-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s156_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 26
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-elect-one-vindicated-on-the-throne-and-the-kings-condemned-in-1-enoch-46-48-62-63',
     'the-blood-of-the-new-covenant-and-the-faithful-unto-death-for-the-covenant-in-1-and-2-maccabees',
     'the-cup-of-the-faithful-servants-drunk-faithful-unto-death-in-4-maccabees',
     'the-shepherd-smitten-and-the-temple-veil-rent-in-the-testaments-of-the-twelve',
     'the-betrayer-the-double-tongue-and-the-watch-against-temptation-in-sirach'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-elect-one-vindicated-on-the-throne-and-the-kings-condemned-in-1-enoch-46-48-62-63',
     'the-blood-of-the-new-covenant-and-the-faithful-unto-death-for-the-covenant-in-1-and-2-maccabees',
     'the-cup-of-the-faithful-servants-drunk-faithful-unto-death-in-4-maccabees',
     'the-shepherd-smitten-and-the-temple-veil-rent-in-the-testaments-of-the-twelve',
     'the-betrayer-the-double-tongue-and-the-watch-against-temptation-in-sirach'
   );

  RAISE NOTICE 'S156 Matt 26 verify: extras xrefs from canon/matthew/26 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 19 THEN
    RAISE EXCEPTION 'Expected at least 19 Matt-26 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 19 THEN
    RAISE EXCEPTION 'Expected at least 19 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
